import { lazy } from 'react';
import { BookOpen as IcBookOpen, CalendarCheck as IcCalendarCheck, Cpu as IcCpu, Layers as IcLayers, ListTree as IcListTree } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Accounting — hub page for the Finance menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 4 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'FinanceAccounting'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const AccountingEngine = lazy(() => import('./AccountingEngine'));
const ChartOfAccounts = lazy(() => import('./ChartOfAccounts'));
const PeriodClosing = lazy(() => import('./PeriodClosing'));
const CostCenters = lazy(() => import('./CostCenters'));

export const TABS = [
  { id: 'engine', label: 'Accounting Engine', icon: IcCpu, page: 'AccountingEngine', Component: AccountingEngine },
  { id: 'coa', label: 'Chart of Accounts', icon: IcListTree, page: 'ChartOfAccounts', Component: ChartOfAccounts },
  { id: 'close', label: 'Period Closing', icon: IcCalendarCheck, page: 'PeriodClosing', Component: PeriodClosing },
  { id: 'cc', label: 'Cost Centres', icon: IcLayers, page: 'CostCenters', Component: CostCenters },
];

export default function FinanceAccounting({ setPage }) {
  return (
    <TabHub
      icon={IcBookOpen}
      eyebrow="Finance"
      title="Accounting"
      subtitle="The accounting engine, chart of accounts, period close and cost centres"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
